package school.magiccodex.client;
import java.awt.*;import java.nio.file.*;import java.util.List;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import school.magiccodex.protocol.NameplateProtocol.TitleRun;
class NameplateTitleRenderingTest {
 private Font font()throws Exception{try(var in=Files.newInputStream(Path.of("src/main/resources/assets/magiccodex/font/pretendard_bold.ttf"))){return Font.createFont(Font.TRUETYPE_FONT,in);}}
 @Test void concatenatedColoredLineUsesWholeRealLayoutAndKeepsBothColors()throws Exception{var font=font();var runs=List.of(new TitleRun("소환술",0x96e4ec),new TitleRun("교수",0xdec58e));assertEquals(CodexTextRasterizer.width(font,"소환술교수",96),CodexTextRasterizer.titleWidth(font,runs,96),.01);var image=CodexTextRasterizer.rasterizeTitles(font,runs,96);boolean first=false,second=false;for(int y=0;y<image.getHeight();y++)for(int x=0;x<image.getWidth();x++){int c=image.getRGB(x,y);if((c>>>24)==255){first|=(c&0xffffff)==0x96e4ec;second|=(c&0xffffff)==0xdec58e;}}assertTrue(first);assertTrue(second);}
 @Test void longCombinedTitleFitsOneSharedBudgetAndEmptySidesStayEmpty()throws Exception{var font=font();var runs=List.of(new TitleRun("매우긴마법연구칭호".repeat(3),0x96e4ec),new TitleRun("최고의대마법학교교수".repeat(3),0xdec58e));float measured=CodexTextRasterizer.titleWidth(font,runs,96);float size=NameplateTitleLayout.fittedSize(measured,96,1080);assertTrue(size<96);assertTrue(CodexTextRasterizer.titleWidth(font,runs,size)<=1081);assertTrue(CodexTextRasterizer.rasterizeTitles(font,runs,size).getWidth()<=1090);assertEquals(0,CodexTextRasterizer.titleWidth(font,List.of(),96));}
 @Test void nameUsesIdenticalBaseFontAndRasterWithOrWithoutTitlesOnlyPositionMoves()throws Exception{var font=font();assertEquals(210,NameplatePolicy.NAME_SIZE);assertEquals(29,NameplatePolicy.nameCenterY(false));assertEquals(85,NameplatePolicy.nameCenterY(true));for(String name:List.of("황준우","아주아주아주긴마법학교이름")){float size=NameplatePolicy.NAME_SIZE*Math.min(1,1100/CodexTextRasterizer.width(font,name,NameplatePolicy.NAME_SIZE));var absent=CodexTextRasterizer.rasterize(font,name,size);var present=CodexTextRasterizer.rasterize(font,name,size);assertEquals(absent.getWidth(),present.getWidth());assertEquals(absent.getHeight(),present.getHeight());for(int y=0;y<absent.getHeight();y++)for(int x=0;x<absent.getWidth();x++)assertEquals(absent.getRGB(x,y),present.getRGB(x,y));}}
}
